import{_ as t,o as a,c as o,a4 as l}from"./chunks/framework.9tZL7ZIQ.js";const b=JSON.parse('{"title":"2006年 · 破纪录之年","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/2006年.md","filePath":"05_quotes/by-year/2006年.md"}'),r={name:"05_quotes/by-year/2006年.md"};function s(c,e,u,h,_,q){return a(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="_2006年-·-破纪录之年" tabindex="-1">2006年 · 破纪录之年 <a class="header-anchor" href="#_2006年-·-破纪录之年" aria-label="Permalink to &quot;2006年 · 破纪录之年&quot;">​</a></h1><blockquote><p>我们不愿意以不反映我们对损失概率评估的价格承担即使是极小的风险。适当的价格不能保证在任何特定年份盈利，但不适当的价格几乎肯定保证最终会亏损。——巴菲特（76岁）</p></blockquote><p>本页收录2006年致股东信中的经典语录。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>如果你想获得好商人的声誉，一定要进入好行业。</p></blockquote><blockquote><p>没有规则说报纸收入不能低于支出，损失不会激增。</p></blockquote><blockquote><p>拥有希望钻石一部分，好过拥有整颗莱茵石。</p></blockquote><blockquote><p>一个有经验的人向一个有钱的人提议交易时，太多的结果是有钱的人得到了经验，而有经验的人得到了钱。</p></blockquote><blockquote><p>ISCAR赚钱，因为它能让客户赚更多钱。没有比这更好的持续成功配方了。</p></blockquote><blockquote><p>当一个行业的基本经济正在崩溃时，有才能的管理者可能会减缓衰退的速度。但最终，侵蚀的基本面将压倒管理才华。</p></blockquote><blockquote><p>我们在这里的行为类似于我们在金融市场中采用的方式：在别人贪婪时恐惧，在别人恐惧时贪婪。</p></blockquote><blockquote><p>成功的长期投资远不止智慧和最近表现良好。</p></blockquote><blockquote><p>性情也很重要。独立思考、情绪稳定以及对人类和机构行为的敏锐理解对长期投资成功至关重要。</p></blockquote><blockquote><p>如果不是人，他们不会被诱惑去阻止可能威胁其生计的行动。</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>2006年伯克希尔净资产增长169亿美元创美国企业纪录，每股账面价值增长18.4%。巴菲特完成首笔海外重大收购——以色列ISCAR，并与Equitas签订巨额追溯再保险合同。本年他深刻剖析报业衰退、CEO薪酬乱象和&quot;2和20&quot;对冲基金收费模式，讲述沃尔特·施洛斯47年无需内幕信息持续跑赢市场的故事，驳斥有效市场理论。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><h2 id="_01-letters-2006年-翻译-·-01-letters-2006年-核心总结-·-01-letters-2006年-思维导图" tabindex="-1"><a href="/01_letters/2006年/翻译.html">01_letters/2006年/翻译</a> · <a href="/01_letters/2006年/核心总结.html">01_letters/2006年/核心总结</a> · <a href="/01_letters/2006年/思维导图.html">01_letters/2006年/思维导图</a> <a class="header-anchor" href="#_01-letters-2006年-翻译-·-01-letters-2006年-核心总结-·-01-letters-2006年-思维导图" aria-label="Permalink to &quot;[[→ 原文翻译|01_letters/2006年/翻译]] · [[→ 核心总结|01_letters/2006年/核心总结]] · [[→ 思维导图|01_letters/2006年/思维导图]]&quot;">​</a></h2><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><ul><li><a href="/01_letters/2006年/翻译.html">/01_letters/2006年/翻译</a></li></ul>',23)])])}const p=t(r,[["render",s]]);export{b as __pageData,p as default};
